-- Fix mod-druid-glyph-forms: the module targeted spell 58161, which is only
-- the momentary "apply glyph" cast fired when socketing the glyph (item
-- 43331's spellid_1). The persistent glyph-effect aura players actually have
-- while the glyph is slotted is a different spell, 57857 (GlyphProperties.dbc
-- entry 434's SpellId) - HasAura(58161) was always false, so the classic-form
-- override never triggered and the Rebirth reagent waiver (SPELL_AURA_NO_
-- REAGENT_USE, not a mana-cost reduction despite the name) was never
-- actually neutralized either. See modules/mod-druid-glyph-forms/README.md.

-- 1. Item tooltip flavor text: describe the actual behavior instead of the
--    placeholder wording from the initial base/ row.
UPDATE `item_template` SET `description` = 'Bear Form, Dire Bear Form, and Cat Form use their original forms.' WHERE `entry` = 43331;

-- 2. Rebind the reagent-waiver-neutralizing script from 58161 to 57857, the
--    spell that actually carries the SPELL_AURA_NO_REAGENT_USE/EFFECT_0 effect.
DELETE FROM `spell_script_names` WHERE `spell_id` = 58161 AND `ScriptName` = 'spell_dru_glyph_of_unburdened_rebirth';
DELETE FROM `spell_script_names` WHERE `spell_id` = 57857 AND `ScriptName` = 'spell_dru_glyph_of_unburdened_rebirth';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(57857, 'spell_dru_glyph_of_unburdened_rebirth');

-- 3. Rename both spell IDs via the spell_dbc -> Spell.dbc pipeline (dbtodbc):
--    58161's text is what the item's "Use:" tooltip line pulls from, 57857's
--    is what the Glyphs UI panel shows once slotted. Full-row snapshots
--    (not sparse inserts) because spell_dbc's non-text columns are
--    NOT NULL DEFAULT '0' - a sparse insert would zero out every other field
--    of the spell instead of leaving it as a pass-through.

-- spell 58161
DELETE FROM `spell_dbc` WHERE `ID` = 58161;
